package com.lexorion.core.audit;
import java.util.UUID;import org.slf4j.MDC;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Propagation;import org.springframework.transaction.annotation.Transactional;
@Service public class AuditRecorder{private final AuditEventRepository events;public AuditRecorder(AuditEventRepository events){this.events=events;}@Transactional(propagation=Propagation.REQUIRES_NEW) public void record(UUID actor,String operation,String resourceType,String resourceId,String result){record(actor,null,null,operation,resourceType,resourceId,result);}@Transactional(propagation=Propagation.REQUIRES_NEW) public void record(UUID actor,UUID organization,UUID workspace,String operation,String resourceType,String resourceId,String result){events.save(new AuditEvent(actor,organization,workspace,operation,resourceType,resourceId,result,MDC.get("correlationId"),"{}"));}}
